using System;using System.IO;using System.Collections.Generic;using StayAwake;
class Fake:IPower {public Guid Plan=Guid.NewGuid();public Dictionary<Guid,uint[]> Values=new Dictionary<Guid,uint[]>();public bool FailDC;public bool FailNormalDC;public Fake(){Values[Plan]=new uint[]{1,2};}public Guid Active(){return Plan;}public uint Read(Guid p,bool ac){return Values[p][ac?0:1];}public void Write(Guid p,bool ac,uint v){if(!ac&&FailNormalDC&&v==1)throw new Exception("normal write denied");if(!ac&&FailDC&&v==0)throw new Exception("write denied");Values[p][ac?0:1]=v;}public void Apply(Guid p){} }
class Tests {
 static int count;static void Assert(bool b,string name){if(!b)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static void Main(){var dir=Path.Combine(Path.GetTempPath(),"stayawake-tests-"+Guid.NewGuid());Directory.CreateDirectory(dir);var f=new Fake();var s=new PowerService(f,Path.Combine(dir,"session.xml"));s.Enable();Assert(s.Verified(),"AC and DC verified after enable");s.Restore();Assert(f.Read(f.Plan,true)==1&&f.Read(f.Plan,false)==2&&!s.HasSession,"original values restored and journal removed");s.Enable();f.Write(f.Plan,true,3);s.Restore();Assert(f.Read(f.Plan,true)==3&&f.Read(f.Plan,false)==2,"manual nonzero change preserved");f.FailDC=true;try{s.Enable();throw new Exception("expected failure");}catch(Exception e){Assert(e.Message=="write denied","write failure reported");}Assert(f.Read(f.Plan,true)==3&&!s.HasSession,"partial write rolled back");f.FailDC=false;s.Enable();var original=f.Plan;f.Plan=Guid.NewGuid();f.Values[f.Plan]=new uint[]{2,3};Assert(!s.Verified(),"power-plan change detected");s.Restore();Assert(f.Read(original,true)==3&&f.Read(f.Plan,true)==2,"original plan restored without modifying new plan");s.Enable();var recovered=new PowerService(f,Path.Combine(dir,"session.xml"));recovered.Restore();Assert(!s.HasSession&&f.Read(f.Plan,true)==2,"persisted session recovered");f.Values[f.Plan]=new uint[]{0,0};s.Enable();s.UseNormalMode();Assert(f.Read(f.Plan,true)==1&&f.Read(f.Plan,false)==1&&s.AllowsLidSleep(),"explicit disable replaces original zero baseline with sleep");f.Values[f.Plan]=new uint[]{0,2};s.UseNormalMode();Assert(f.Read(f.Plan,true)==1&&f.Read(f.Plan,false)==2,"normal mode preserves existing hibernate setting");f.Values[f.Plan]=new uint[]{0,0};f.FailNormalDC=true;try{s.UseNormalMode();throw new Exception("expected failure");}catch(Exception e){Assert(e.Message=="normal write denied"&&s.HasSession&&!s.AllowsLidSleep(),"normal-mode failure retains recovery journal");}f.FailNormalDC=false;s.UseNormalMode();Assert(!s.HasSession&&s.AllowsLidSleep(),"normal-mode retry completes both settings");f.Values[f.Plan]=new uint[]{0,0};s.Enable();s.Restore();Assert(f.Read(f.Plan,true)==0&&f.Read(f.Plan,false)==0,"automatic recovery still preserves exact zero baseline");Console.WriteLine(count+" tests passed");Directory.Delete(dir,true);}
}
